    "purpose": "Gıda Mikrobiyolojisi alanındaki ileri düzey kavramları, biyolojik mekanizmaları ve bilimsel kanıtları çözümleyerek alanla ilgili verileri uygun yöntemlerle değerlendirme yetkinliği kazandırmak.",
    "content": "Gıda Mikrobiyolojisi; Gıda mikrobiyolojisinin kapsamı, Gıdalarda mikrobiyal gelişmeyi belirleyen iç faktörler, Dış çevre faktörleri ve mikrobiyal gelişme, Gıda kaynaklı bakteriyel patojenler, Gıda kaynaklı virüs ve parazitler, veri ve kanıtların değerlendirilmesi, etik ilkeler ve güncel bilimsel gelişmeler çerçevesinde ele alınır.",
    "methods": "Kuramsal anlatım, mikrobiyolojik bulgu yorumlama, vaka analizi, bilimsel makale incelemesi ve problem çözme.",
    "resources": "Biyoloji alanındaki güncel hakemli makaleler; Gıda Mikrobiyolojisi konusunda lisansüstü düzey temel kaynaklar; ilgili ulusal ve uluslararası bilimsel veri tabanları.",
