    "purpose": "Bu dersin amacı laboratuarda çalışırken kazaların önlenmesi bakımından dikkat edilecek hususlar ve alınması gerekli önlemleri, bitki ve toprak örnekleme yöntemlerini, örneklerin analize hazırlanmasını, bazı fiziksel ve kimyasal analizleri ve bu analizlerden elde edilecek sonuçların değerlendirilmesi ve yorumlanmasını sağlamaktır.",
    "content": "Laboratuarda çalışırken kazaların önlenmesi bakımından dikkat edilecek hususlar ve alınması gerekli önlemlerLaboratuarda kullanılan cam ve kimyasal malzemelerin tanıtımı Bitki ve toprak analizlerinde kullanılan cihazların tanıtımı ve çalışma prensipleriBitki ve toprak örnekleme yöntemleriÖrneklerin analize hazırlanmasıBazı fiziksel ve kimyasal analizlerAnalizler sonuçlarının değerlendirilmesi ve yorumlanması",
    "methods": "Yüzyüze anlatım, fiziksel ve kimyasal analizleri laboratuarda uygulama.",
