    "purpose": "Endokrin sistem tarafından salgılanan hormonların (kimyasal haberciler) salınımının genetik düzeyden başlayarak düzenlenmenin öğretilmesi. Endokrin sistem içerisinde yer alanbezlerin hormonal salgılarının yapısı ve işleyiş mekanizmalarının öğretilmesi. Hormonal senkronizasyonda sırasında meydana gelebilecek aksaklıkların tespiti ve çözüm önerilerininöğretilmesi.",
    "content": "Endokrin sistem ve salgıladığı hormonların görevlerinin ve etkileşimlerinin öğretilmesi",
    "methods": "Hormonların yapısı, Hormonların sınıflandırılması, Hormon salgılayan endokrin bezler, Endokrin bezlerin çalışmasının düzenlenmesi ve kontrolü, Hormon reseptörleri, Hormonalsenkronizasyon nedir? Hormonal senkronizasyonun kontrolü, Hormonal senkronizasyonun kontrolü (genetik), Hipotamusun hormonal senkronizasyondaki rolü, Hipofiz bezi aktivitesive endokrin bezler üzerine etkisi, Hipotalamus-hipofizer-tiroit aksı, Hipotalamus-hipofizer-adrenal aks, Hipotamus-hipofiz-gonad aksı, Hormonal senronizasyonda görülen aksamalarve çözüm önerileri.",
    "resources": "Kaynaklar: Noyan, A. (2003) Yaşamda ve Hekimlikte Fizyoloji. Meteksan. Ankara.; Ders Notları: Noyan, A. (2003) Yaşamda ve Hekimlikte Fizyoloji. Meteksan. Ankara.",
