      "İnsanda kalıtsal hastalıklar: örnek araştırmaların karşılaştırılması",
      "sonuçların biyolojik yorumlanması: bulguların yorumlanması",
      "İnsanda kalıtsal hastalıklar: disiplinler arası bağlantılar",
      "İnsanda kalıtsal hastalıklar: etik, güvenlik ve sınırlılıklar",
      "İnsanda kalıtsal hastalıklar: çevresel veya toplumsal etkilerin değerlendirilmesi",
      "İnsanda kalıtsal hastalıklar: güncel literatürün eleştirel incelenmesi",
      "İnsanda kalıtsal hastalıklar: bütünleşik bilimsel değerlendirme"
