    "content": "Bilimsel problem ve hipotez, biyolojik araştırma desenleri, örnekleme, veri toplama ve kalite güvencesi, temel analiz yaklaşımları, bilimsel yazım, araştırma bütünlüğü, yayın etiği ve biyogüvenlik.",
