    "purpose": "Fungal organizmaların biyolojik ve ekolojik önemleri, taksonomik pozisyonları, morfolojik, sitolojik, metabolik özelliklerinin tanıtılması",
    "content": "Fungal Aleme genel bakış, Fungus grubunun genel sitolojik, fizyolojik morfolojik ve ekolojik karakteristikleri, Fungusların taksonomik yeri sınıflandırılması ve teşhis kriterleri, Fungi dizyonları, Fungal büyüme ve bunlara bağlı taksonlar, fungal evolüsyon, Sporülasyon ve sporlar, Fermentatif ve biyoteknolojik kullanım olanakları, Fungal Saprofitizm, Biodegradasyon ve bioeremidation özellikleri ve kullanımları, Tarım ve Veterinerlik alanında Fungal organizmalar",
    "methods": "Yüzyüze",
    "resources": "Kaynaklar: 1234; Ders Notları: Öğretim üyesi tarafından verilen ders notları",
