    "prerequisites": "Yok",
    "purpose": "Bu dersin amacı, öğrencilere doğal, kozmetik ve tıbbi ürünler hakkında bilgi ve farkındalık sağlamaktır. Bu ürünlerin önemi, bileşenleri, üretim süreçleri ve kullanımları da dahil olmak üzere konular üzerine eğitim vermek hedeflenmektedir. Dersin amaçları arasında, doğal kozmetik ve tıbbi ürünlerin kimyasal alternatiflere göre avantajları, etkinlikleri ve riskleri hakkında öğrencileri bilgilendirmek; doğal içeriklerin sağlık üzerindeki etkilerini incelemek ve doğal ürünlerin sürdürülebilirlik ve çevresel etkilerini tartışmak yer alır. Ayrıca, ders, öğrencilerin doğal kozmetik ve tıbbi ürünlerle ilgili pazarlama stratejilerini, düzenlemeleri ve tüketici davranışlarını anlamalarını ve eleştirel bir şekilde değerlendirmelerini amaçlar. Ayrıca, endüstrideki yenilikleri ve gelecek perspektiflerini değerlendirme yeteneklerini geliştirmeyi hedefler.",
    "content": "Bitkisel tedavi ve Farmakognozi temel kavramları, bitki ikincil metabolitleri, çeşitli sistem hastalıklarında kullanılan doğal ürünler, aromaterapi, besin destekleri, Türkiye'de doğal ürünlerle ilgili yasal düzenlemeler ve mevzuatlar. Kozmetik tanımı, Kozmetik taşıyıcı sistemler, Anti-aging ürünler, Bebek kozmetiği, Selülit ürünleri, Güneş koruyucu ürünler, Sabunlar, Antiperspiranlar ve deodorantlar, Renkli kozmetikler, Saç boyaları ve bakım ürünleri, Şampuanlar, Tıraş için kullanılan ürünler, Ayak bakımı ve banyo ürünleri, Kozmetiklerin yan etkileri ve mikrobiyolojik özellikleri, Kozmetiklerin stabilitesi ve depolanması, Etiketleme, ambalajlama ve yasal düzenlemeler.",
    "methods": "Powerpoit sunumları ile yüzyüze öğretme",
    "resources": "Kaynaklar: Tanker, M., Tanker, N., 1998. Farmakognozi, Ankara Üniv. Eczacılık Fak. Yayınları, Ankara.Tohumlu Bitkilerde Sekonder Metabolitler, Nobel Akademik Yayıncılık; Ders Notları: Stamets, P. (2011). Growing gourmet and medicinal mushrooms. Ten speed press.Schmelzer, G. H., Gurib-Fakim, A., & Schmelzer, G. H. (Eds.). (2008). Medicinal plants (Vol. 11). Prota.",
