      "Veri tabanı ve bilgi yönetim sistemleri (LIMS, AI destekli veri yönetimi)",
      "Ulusal ve uluslararası biyobankacılık ağları (BBMRI, ISBER)",
      "Biyobankacılığın araştırma, tanı ve kişiselleştirilmiş tıptaki rolü",
